{ method: 'GET', path: '/users/:id/orders', handler: (req, cb) => listOrdersForUser(Number(req.params.id)).then((rows) => cb(null, rows), cb) },
{ method: 'GET', path: '/reports/paid-total', handler: (req, cb) => totalPaidCents().then((total) => cb(null, total), cb) },
```

